import {icon,avatar} from './ui.js';
const top=(title,subtitle,action='Open workspace',href='#/app/overview')=>`<div class="preview-page-heading"><div><span>YOUR RECOVERY WORKSPACE</span><h3>${title}</h3><p>${subtitle}</p></div><a href="${href}" class="preview-button">${action} ${icon('arrow')}</a></div>`;
export function workspacePreview(view='jobs'){
  if(view==='network')return `${top('The right specialist.','Compare task fit, price, and acceptance checks.','Compare in the console','#/app/market')}<div class="preview-provider-grid">${[['Patch','Structured data repair','6.40','JSON · CSV','patch'],['Atlas','Extraction & enrichment','8.20','Documents · Sources','atlas'],['Mender','Validation & schema repair','7.50','Schema · Deduplication','mender']].map(([name,skill,price,tags,id],i)=>`<a href="#/app/market/${id}" class="preview-provider">${avatar(i,'avatar-lg')}<span class="preview-provider-id">SPECIALIST / 00${i+1}</span><h4>${name}</h4><p>${skill}</p><div>${tags}</div><span>Sample quote<strong>${price}<small> USDC</small></strong></span>${icon('arrow')}</a>`).join('')}</div><div class="preview-note">${icon('info')} Patch takes structured-data jobs. Quotes cover the leftover rows.</div>`;
  if(view==='receipt')return `${top('A result you can inspect.','Acceptance first. A clear record of what happened.','Inspect the receipt','#/app/receipts')}<div class="preview-receipt-layout"><div class="preview-validation"><div class="preview-subhead">${icon('shield')} ACCEPTANCE CHECKS <span>4 / 4</span></div>${[['Schema','Required fields match the agreed format.'],['Completeness','100 of 100 expected records present.'],['Uniqueness','No duplicate primary identifiers.'],['Preservation','The original 70 records remain unchanged.']].map(([a,b])=>`<div><span class="check-seal">${icon('check')}</span><span><strong>${a}</strong><small>${b}</small></span><b>Passed</b></div>`).join('')}</div><div class="preview-receipt"><span class="receipt-perforation"></span><small>RECOVERY RECEIPT</small><h4>Good work,<br>accounted for.</h4><div><span>Specialist</span><strong>Patch</strong></div><div><span>Recovery quote</span><strong>6.40 USDC</strong></div><div><span>Platform fee</span><strong>0.32 USDC</strong></div><div class="preview-receipt-total"><span>Total</span><strong>6.72 USDC</strong></div><p>USDC moves only after you accept the output.</p><a href="#/app/receipts">Open receipts ${icon('right')}</a></div></div>`;
  return `${top('Every checkpoint is a head start.','A clear path from interrupted to complete.','Try a recovery')}<div class="preview-stat-row">${[['Needs recovery','02','Ready for a specialist'],['Awaiting review','01','Your acceptance checks'],['Verified','01','A complete recovery loop']].map(([label,n,small],i)=>`<div><span>${label}${icon(i===0?'refresh':i===1?'eye':'shield')}</span><strong>${n}<i>${i===0?'↗':i===1?'—':'✓'}</i></strong><small>${small}</small></div>`).join('')}</div><div class="preview-jobs"><div class="preview-table-head"><span>RECOVERY PACKAGE</span><span>PROGRESS</span><span>STATUS</span><span>BUDGET CAP</span><span></span></div>${[['Customer dataset enrichment','RW-024 · Structured data','70','Needs rescue','10.00','orange','RW-024'],['Invoice extraction · October','RW-023 · Document extraction','100','Awaiting review','8.00','amber','RW-023'],['Product catalog normalization','RW-022 · Structured data','100','Verified','6.00','green','RW-022']].map(([title,sub,n,status,budget,color,id])=>`<a class="preview-job-row" href="#/app/jobs/${id}"><span><i class="preview-file">${icon('file')}</i><span><strong>${title}</strong><small>${sub}</small></span></span><span class="preview-job-progress"><i style="--progress:${n}%"><b></b></i>${n}%</span><span><b class="status ${color}"><i></i>${status}</b></span><span>${budget}<small> USDC</small></span>${icon('right')}</a>`).join('')}</div><div class="preview-note">${icon('info')} Finished rows stay put. Payment waits until you accept.</div>`;
}
